mapper.select:
SELECT COUNT(*)
FROM dormitory_building
WHERE building_code=#{buildingCode}
  AND id<>#{buildingId}

SELECT COUNT(*)
FROM room
JOIN dormitory_floor floor ON floor.id=room.floor_id
WHERE floor.building_id=#{buildingId}
  AND floor.floor_number>#{floorCount}

mapper.update:
UPDATE dormitory_floor
SET enabled=1
WHERE building_id=#{buildingId}
  AND floor_number<=#{floorCount}

UPDATE dormitory_floor
SET enabled=0
WHERE building_id=#{buildingId}
  AND floor_number>#{floorCount}

mapper.insert:
INSERT INTO dormitory_floor (building_id, floor_number, floor_name, enabled)
SELECT #{buildingId}, #{floorNumber}, #{floorName}, 1
WHERE NOT EXISTS (
    SELECT 1
    FROM dormitory_floor
    WHERE building_id=#{buildingId}
      AND floor_number=#{floorNumber}
)
